files.content:
.ds .ds-token-radius { display:flex; gap:12px; }
.ds .ds-token-radius i { width:48px; height:48px; border:2px solid currentColor; border-radius:var(--p-inner-radius); }
.ds .ds-token-radius [data-token="control"] { border-radius:var(--p-control-radius); }
.ds .ds-token-radius [data-token="surface"] { border-radius:var(--p-radius); }
